        if not self.active:
            raise TxError('no tx')
        for k, (op, v) in self.staged.items():
            if op == 'put':
                self.data[k] = v
            else:
                self.data.pop(k, None)
        self.staged = {}
        self.active = False

    def rollback(self):
        if not self.active:
            raise TxError('no tx')
