        keys = set(self.data) | {kk for _, kk, _ in self.staged}
        return [k for k in sorted(keys) if self.get(k) is not None]

    def commit(self):
        if not self.active:
            raise TxError('no tx')
        for op, k, v in self.staged:
            if op == 'put':
                self.data[k] = v
            else:
                self.data.pop(k, None)
        self.staged = []
        self.active = False

    def rollback(self):
        if not self.active:
            raise TxError('no tx')
        if self.staged:
            self.staged.pop()
        self.active = False

